        fails.append(name); print("FAIL", name, repr(ex))
    finally:
        if p.exists(): p.unlink()

def t1():
    p.write_bytes(json.dumps(good("t",1,ZERO)).encode()+b"\n"+b"{\"tenant\":\xff}")
    assert c.verify("t")=={"ok":False,"at":2,"reason":"missing"}
    assert c.verify_all()=={"ok":False,"at":2,"tenant":None,"reason":"missing"}
case("illegal byte last line no newline", t1)

