    r=c.verify_all(); assert r=={"ok":False,"at":1,"tenant":"t","reason":"digest"}, r
case("earlier digest wins over bad bytes", t5)

def t6():
    p.write_bytes(json.dumps(good("t",2,ZERO)).encode()+b"\n\xff")
    assert c.verify("t")=={"ok":False,"at":1,"reason":"sequence"}
case("earlier sequence wins", t6)

def t7():
